/**
 * OpenClaw MCP Demo
 * Demonstrates MCP server management and state persistence
 */

import * as fs from 'fs';
import * as path from 'path';

// ============ MCP Server Management ============

interface MCPServerConfig {
  command: string;
  args: string[];
  status?: string;
}

interface MCPServer {
  id: string;
  config: MCPServerConfig;
  status: 'active' | 'inactive' | 'error';
  tools: string[];
}

class MCPSystem {
  private servers: Map<string, MCPServer> = new Map();
  private initialized: boolean = false;

  // Simulated filesystem server tools
  private fsTools: string[] = [
    'read_file',
    'write_file',
    'list_directory',
    'create_directory',
    'delete_file',
    'move_file',
    'search_files'
  ];

  addMcpServer(id: string, config: MCPServerConfig): MCPServer {
    const server: MCPServer = {
      id,
      config,
      status: 'inactive',
      tools: []
    };
    this.servers.set(id, server);
    console.log(`[MCP] Server registered: ${id}`);
    return server;
  }

  async initializeMcpSystem(): Promise<void> {
    console.log('[MCP] Initializing MCP system...');
    for (const [id, server] of this.servers) {
      if (id === 'filesystem') {
        server.tools = [...this.fsTools];
      }
      server.status = 'active';
      console.log(`[MCP] Server ${id} initialized with ${server.tools.length} tools`);
    }
    this.initialized = true;
    console.log('[MCP] System initialization complete');
  }

  getAllTools(): Map<string, string[]> {
    const tools = new Map<string, string[]>();
    for (const [id, server] of this.servers) {
      if (server.status === 'active') {
        tools.set(id, server.tools);
      }
    }
    return tools;
  }

  getActiveServerIds(): string[] {
    return Array.from(this.servers.entries())
      .filter(([_, s]) => s.status === 'active')
      .map(([id, _]) => id);
  }

  getTotalToolCount(): number {
    let count = 0;
    for (const server of this.servers.values()) {
      if (server.status === 'active') {
        count += server.tools.length;
      }
    }
    return count;
  }
}

// ============ State Persistence ============

interface PersistedState {
  count: number;
  items: string[];
  _hydrated: boolean;
}

class PersistStore {
  private storeName: string;
  private filePath: string;
  private state: PersistedState;
  private hydrated: boolean = false;

  constructor(storeName: string, initialState: { count: number; items: string[] }) {
    this.storeName = storeName;
    this.filePath = path.join(process.cwd(), '.persist_store.json');
    this.state = { ...initialState, _hydrated: false };
    this.load();
  }

  load(): void {
    try {
      if (fs.existsSync(this.filePath)) {
        const data = JSON.parse(fs.readFileSync(this.filePath, 'utf-8'));
        this.state = { ...this.state, ...data };
        this.hydrated = true;
        console.log(`[Store] State hydrated from disk: count=${this.state.count}, items=${this.state.items.length}`);
      } else {
        console.log('[Store] No persisted state found, using initial state');
      }
    } catch (err) {
      console.log('[Store] Error loading state:', err);
    }
  }

  save(): void {
    const data = { ...this.state, _hydrated: undefined };
    fs.writeFileSync(this.filePath, JSON.stringify(data, null, 2));
    console.log(`[Store] State persisted: count=${this.state.count}, items=${this.state.items.length}`);
  }

  getState(): PersistedState {
    return { ...this.state };
  }

  getHydrated(): boolean {
    return this.hydrated;
  }

  increment(): void {
    this.state.count += 1;
  }

  addItem(item: string): void {
    this.state.items.push(item);
  }
}

// ============ Main Demo ============

async function main() {
  console.log('='.repeat(50));
  console.log('OpenClaw MCP Demo');
  console.log('='.repeat(50));

  // Load MCP config
  const configPath = path.join(process.cwd(), 'mcp_config.json');
  const mcpConfig = JSON.parse(fs.readFileSync(configPath, 'utf-8'));
  console.log('\n[Config] Loaded MCP config:', configPath);

  // Create MCP system
  const mcpSystem = new MCPSystem();

  // Check tools BEFORE initialization
  console.log('\n--- Before Initialization ---');
  const toolsBefore = mcpSystem.getAllTools();
  console.log(`Active servers: ${mcpSystem.getActiveServerIds().join(', ') || 'none'}`);
  console.log(`Total tools: ${mcpSystem.getTotalToolCount()}`);

  // Register filesystem server from config
  const fsServerConfig = mcpConfig.mcpServers.filesystem;
  mcpSystem.addMcpServer('filesystem', fsServerConfig);

  // Initialize MCP system
  await mcpSystem.initializeMcpSystem();

  // Check tools AFTER initialization
  console.log('\n--- After Initialization ---');
  const toolsAfter = mcpSystem.getAllTools();
  const activeServers = mcpSystem.getActiveServerIds();
  const totalTools = mcpSystem.getTotalToolCount();
  console.log(`Active servers: ${activeServers.join(', ')}`);
  console.log(`Total tools: ${totalTools}`);
  for (const [serverId, tools] of toolsAfter) {
    console.log(`  ${serverId}: [${tools.join(', ')}]`);
  }

  // State Persistence Demo
  console.log('\n--- State Persistence Demo ---');
  const store = new PersistStore('mcp-demo-store', { count: 0, items: [] });

  console.log(`Hydrated on load: ${store.getHydrated()}`);

  // Write one counter value (increment)
  store.increment();

  // Write one item to persistent store
  store.addItem('demo-item-001');

  // Persist to disk
  store.save();

  const finalState = store.getState();
  console.log(`Final state: count=${finalState.count}, items=[${finalState.items.join(', ')}]`);

  // Write summary output
  const outputDir = path.join(process.cwd(), 'output');
  if (!fs.existsSync(outputDir)) {
    fs.mkdirSync(outputDir, { recursive: true });
  }

  const summary = {
    timestamp: new Date().toISOString(),
    activeServerIds: activeServers,
    totalToolCount: totalTools,
    toolsByServer: Object.fromEntries(toolsAfter),
    persistence: {
      hydrated: store.getHydrated(),
      counterValue: finalState.count,
      items: finalState.items
    }
  };

  const outputPath = path.join(outputDir, 'mcp_summary.json');
  fs.writeFileSync(outputPath, JSON.stringify(summary, null, 2));
  console.log(`\n[Output] Summary written to: ${outputPath}`);

  console.log('\n' + '='.repeat(50));
  console.log('Demo Complete!');
  console.log('='.repeat(50));
}

main().catch(console.error);
EOF\n",
